sys_script_include.script:
var CaseProcessor = Class.create();
CaseProcessor.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    // ✅ 1. VALIDATE EVENT PAYLOAD
    validateEvent: function(payload) {

        if (!payload) return false;

        if (!payload.event_id || !payload.asset_serial) {
            gs.info("Validation failed: Missing required fields");
            return false;
        }

        return true;
    },

    // ✅ 3. CREATE CASE FROM EVENT (MAIN METHOD)
    createCaseFromEvent: function(payload) {

        try {

            // ✅ Step 1: Validate payload
            if (!this.validateEvent(payload)) {
                return "Invalid payload";
            }

            // ✅ Step 2: Fetch Asset using serial_number
            var assetGR = new GlideRecord('x_1558402_smart_0_asset_table');
            assetGR.addQuery('serial_number', payload.asset_serial);
            assetGR.query();

            if (!assetGR.next()) {
                return "Asset not found";
            }

            // ✅ Step 3: Get Customer from Asset
            var customer = assetGR.customer;

            // ✅ Step 4: Create Case record
            var caseGR = new GlideRecord('x_1558402_smart_0_case_table');
            caseGR.initialize();

            // 🔹 Populate from payload
            caseGR.setValue('description', payload.description);
            caseGR.setValue('external_event_id', payload.event_id);

            // 🔹 Derived values
            caseGR.setValue('asset', assetGR.sys_id);
            caseGR.setValue('customer', customer);

            // 🔹 Priority mapping
			// gs.info("SEVERITY VALUE RECEIVED IS : " + payload.severity);
            // if (payload.severity) {
            //     caseGR.setValue('priority', payload.severity);
            // } else {
            //     caseGR.setValue('priority', 'medium');
            // }

            // 🔹 Default values
            caseGR.setValue('state', 'new');

            var caseSysId = caseGR.insert();

            if (!caseSysId) {
                return "Case creation failed";
            }

            return "Case Created: " + caseSysId;

        } catch (e) {
            gs.error("Error in createCaseFromEvent: " + e.message);
            return "Error creating case";
        }
    },

    // ✅ 4. FETCH CUSTOMER FROM ASSET (GLIDEAJAX)
    getCustomerFromAsset: function() {

        var assetId = this.getParameter('sysparm_asset_id');
        var assetGR = new GlideRecord('x_1558402_smart_0_asset_table');

        if (assetGR.get(assetId)) {
            return assetGR.customer.toString();
        }

        return '';
    },

    // ✅ 5. GET ASSET STATUS (GLIDEAJAX)
    getAssetStatus: function() {

        var assetId = this.getParameter('sysparm_asset_id');
        var assetGR = new GlideRecord('x_1558402_smart_0_asset_table');

        if (assetGR.get(assetId)) {
            return assetGR.status.toString();
        }

        return '';
    },

    type: 'CaseProcessor'
});
